    {{ if eq  .Title  .Site.Title }}{{ .Site.Title }}{{ else }}{{ with .Title }}{{.}} on {{ end }}{{ .Site.Title }}{{ end }}
    {{ .Permalink }}
    Recent content {{ if ne  .Title  .Site.Title }}{{ with .Title }}in {{.}} {{ end }}{{ end }}on {{ .Site.Title }}
    Hugo -- gohugo.io{{ with .Site.LanguageCode }}
    {{.}}{{end}}{{ with .Site.Author.email }}
    {{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Author.email }}
    {{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Copyright }}
    {{.}}{{end}}{{/* Hugo 0.48 dates a list page from the first child page that has a date, so a
    category feed can keep reporting an old page after new pages arrive. Use the newest
    date in the feed instead: the page itself, each item, and each item's own children. */}}{{ $lastBuildDate := .Date }}{{ range .Data.Pages }}{{ if .Date.After $lastBuildDate }}{{ $lastBuildDate = .Date }}{{ end }}{{ range .Pages }}{{ if .Date.After $lastBuildDate }}{{ $lastBuildDate = .Date }}{{ end }}{{ end }}{{ end }}{{ if not $lastBuildDate.IsZero }}
    {{ $lastBuildDate.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}{{ end }}
    {{ with .OutputFormats.Get "RSS" }}
	{{ printf "" .Permalink .MediaType | safeHTML }}
    {{ end }}
    {{ range .Data.Pages }}


      {{ .Title }}
      {{ .Permalink }}
      {{ $itemDate := .Date }}{{ range .Pages }}{{ if .Date.After $itemDate }}{{ $itemDate = .Date }}{{ end }}{{ end }}{{ $itemDate.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
      {{ with .Site.Author.email }}{{.}}{{ with $.Site.Author.name }} ({{.}}){{end}}{{end}}
      {{ .Permalink }}
      {{ .Summary | html }}

